      "documentId": "2c5e9fa0-f301-4278-8e99-a0b1c2d3e4f5",
      "title": "PM Surya Ghar subsidy in Kerala: the complete homeowner guide",
      "slug": "pm-surya-ghar-subsidy-kerala-guide",
      "excerpt": "How much subsidy you get, how to apply on the national portal, and how long KSEB net-metering takes.",
      "summary": [
        {
          "type": "paragraph",
          "children": [
            {
              "type": "text",
              "text": "Households in Kerala can claim up to ₹78,000 central subsidy on a 3 kW rooftop system under PM Surya Ghar."
            }
          ]
        }
      ],
      "introduction": [
        {
          "type": "paragraph",
          "children": [
            {
              "type": "text",
              "text": "This guide walks through eligibility, the national portal application, KSEB net-metering and when the subsidy reaches your bank account."
            }
          ]
        }
      ],
      "readTime": 7,
      "isFeatured": true,
      "sortOrder": null,
      "publishedOn": "2026-10-01T12:05:00+05:30",
      "updatedAt": "2026-10-01T12:05:00+05:30",
      "publishedAt": "2026-10-01T12:05:00+05:30",
      "author": {
        "id": 7,
        "name": "Anjali Menon",
        "bio": "Anjali has designed more than 400 rooftop systems across Ernakulam and Thrissur.",
        "role": "Solar Energy Consultant"
      },
      "categories": [
        {
          "id": 12,
          "name": "Solar subsidies",
          "slug": "solar-subsidies"
        }
      ],
      "tags": [
        {
          "id": 31,
          "name": "PM Surya Ghar"
        }
      ],
      "badges": [
        {
          "id": 4,
          "label": "Buying guide",
          "color": "#ED8723"
        }
      ],
      "contentBlocks": [
        {
          "__component": "shared.rich-text",
          "id": 1031,
          "body": [
            {
              "type": "heading",
              "level": 2,
              "children": [
                {
                  "type": "text",
                  "text": "Who is eligible?"
                }
              ]
            },
            {
              "type": "paragraph",
              "children": [
                {
                  "type": "text",
                  "text": "Any residential KSEB consumer with a valid electricity connection and a shade-free roof can apply. Housing societies get ₹18,000 per kW for common facilities."
                }
              ]
            },
            {
              "type": "list",
              "format": "unordered",
              "children": [
                {
                  "type": "list-item",
                  "children": [
                    {
                      "type": "text",
                      "text": "1–2 kW: ₹30,000 per kW"
                    }
                  ]
                },
                {
                  "type": "list-item",
                  "children": [
                    {
                      "type": "text",
                      "text": "3 kW and above: ₹78,000 (capped)"
                    }
                  ]
                }
              ]
            }
          ]
        },
        {
          "__component": "shared.quote",
          "id": 1032,
          "body": {
            "body": "Our bill dropped from ₹4,200 to ₹310 a month after the 3 kW system went live.",
            "author": "Ramesh Nair, Kakkanad"
          }
        }
      ],
      "coverImage": {
        "url": "https://cdn.goldenray.in/blog/pm-surya-ghar-kerala-rooftop.jpg",
        "width": null,
        "height": null,
        "alternativeText": null
      },
      "warning": "The subsidy is released only after the KSEB net-meter inspection — keep your installer's commissioning report.",
      "insights": "A 3 kW system in Kochi generates roughly 12 units a day, enough for a typical 2BHK home.",
      "seo": {
        "metaTitle": "PM Surya Ghar Subsidy in Kerala (2026) | Goldenray",
